action.code:
if (polygon_coords.empty()) {
    return;
}

std::vector<Triangulation::Vertex_handle> vertex_handles;
vertex_handles.reserve(polygon_coords.size());

for (const auto& coord : polygon_coords) {
    if (coord.size() < 3) {
        continue; // skip malformed coordinate
    }
    Kernel::Point_3 point3(coord[0], coord[1], coord[2]);
    Kernel::Point_3 proj = plane.projection(point3);

    // Locate a face near the projected point using the current walk hint
    Triangulation::Face_handle hint_face = triangulation.locate(proj, walk_start);
    // Insert the point (or retrieve existing vertex) using the hint face
    Triangulation::Vertex_handle vh = triangulation.insert(proj, hint_face);
    vertex_handles.push_back(vh);

    // Update walk_start for the next insertion to keep walking efficient
    walk_start = triangulation.locate(proj, walk_start);
}

// Insert constraints between consecutive vertices, closing the polygon
std::size_t n = vertex_handles.size();
for (std::size_t i = 0; i < n; ++i) {
    Triangulation::Vertex_handle v1 = vertex_handles[i];
    Triangulation::Vertex_handle v2 = vertex_handles[(i + 1) % n];
    triangulation.insert_constraint(v1, v2);
}

